create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text unique not null,name text not null default '',role text not null default 'Viewer' check(role in('Admin','Editor','Viewer')),active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.parameters(id bigint generated by default as identity primary key,category text not null,key text unique not null,value text not null,label text not null,updated_at timestamptz not null default now());
create table if not exists public.control_records(id bigint generated by default as identity primary key,type text not null check(type in('plan','action','risk','assessment','qbo','finance','procurement')),code text not null,title text not null,domain text not null default '',owner text not null default '',priority text not null default 'High',status text not null default 'Not Started',phase text not null default '',day_start integer not null default 1,day_end integer not null default 60,progress numeric(5,2) not null default 0 check(progress between 0 and 100),likelihood integer not null default 0 check(likelihood between 0 and 5),impact integer not null default 0 check(impact between 0 and 5),current_rating numeric(3,1) not null default 0 check(current_rating between 0 and 5),day45_target numeric(3,1) not null default 0,day60_target numeric(3,1) not null default 0,details text not null default '',evidence text not null default '',area text not null default '',evidence_check text not null default '',target_rating numeric(3,1) not null default 5 check(target_rating between 0 and 5),domain_weight numeric(5,4) not null default 0,assessed boolean not null default false,finding text not null default '',corrective_action text not null default '',target_date date,critical_control boolean not null default false,review_notes text not null default '',updated_by uuid references auth.users(id),updated_at timestamptz not null default now(),unique(type,code));
create table if not exists public.audit_logs(id bigint generated by default as identity primary key,user_id uuid references auth.users(id),user_email text,action text not null,record_type text not null,record_code text not null,changes jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists idx_control_records_type on public.control_records(type);create index if not exists idx_control_records_status on public.control_records(status);create index if not exists idx_control_records_due on public.control_records(day_end);
create or replace function public.current_user_role() returns text language sql stable security definer set search_path=public as $$select role from public.profiles where id=auth.uid() and active=true$$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,email,name,role)values(new.id,new.email,coalesce(new.raw_user_meta_data->>'full_name',split_part(new.email,'@',1)),case when not exists(select 1 from public.profiles)then 'Admin' else 'Viewer' end);return new;end;$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.set_record_audit() returns trigger language plpgsql security definer set search_path=public as $$begin new.updated_at=now();new.updated_by=auth.uid();insert into public.audit_logs(user_id,user_email,action,record_type,record_code,changes)values(auth.uid(),coalesce(auth.jwt()->>'email',''),case when tg_op='INSERT'then'Created'else'Updated'end,new.type,new.code,to_jsonb(new));return new;end;$$;
drop trigger if exists audit_control_record on public.control_records;create trigger audit_control_record before insert or update on public.control_records for each row execute function public.set_record_audit();
alter table public.profiles enable row level security;alter table public.parameters enable row level security;alter table public.control_records enable row level security;alter table public.audit_logs enable row level security;
create policy "authenticated read profiles" on public.profiles for select to authenticated using(true);create policy "admins update profiles" on public.profiles for update to authenticated using(public.current_user_role()='Admin') with check(public.current_user_role()='Admin');
create policy "authenticated read parameters" on public.parameters for select to authenticated using(true);create policy "admins manage parameters" on public.parameters for all to authenticated using(public.current_user_role()='Admin') with check(public.current_user_role()='Admin');
create policy "authenticated read records" on public.control_records for select to authenticated using(public.current_user_role() is not null);create policy "editors manage records" on public.control_records for all to authenticated using(public.current_user_role() in('Admin','Editor')) with check(public.current_user_role() in('Admin','Editor'));
create policy "authenticated read audit" on public.audit_logs for select to authenticated using(public.current_user_role() is not null);
insert into public.parameters(category,key,value,label)values('Program','program_start','2026-09-07','Program start date'),('Targets','day_45_target','2.5','Day 45 maturity target'),('Targets','day_60_target','3','Day 60 maturity target'),('Workflow','statuses','Not Started|In Progress|Blocked|Done|Deferred','Allowed statuses'),('Workflow','priorities','Critical|High|Medium|Low','Allowed priorities'),('Risk','critical_min','20','Critical risk threshold'),('Risk','high_min','15','High risk threshold'),('Access','default_role','Viewer','Default user role')on conflict(key)do nothing;
